from __future__ import annotations

from collections import defaultdict
import heapq
from typing import Any


class ResourceIndex:
    def __init__(self, resources: dict[str, dict[str, Any]]) -> None:
        self.resources = resources
        self._depth_cache: dict[str, int] = {}
        self._labels_cache: dict[str, dict[str, str]] = {}

    def depth(self, resource_id: str) -> int:
        cached = self._depth_cache.get(resource_id)
        if cached is not None:
            return cached
        parent_id = self.resources[resource_id]["parent_id"]
        depth = 0 if parent_id is None else self.depth(parent_id) + 1
        self._depth_cache[resource_id] = depth
        return depth

    def effective_labels(self, resource_id: str) -> dict[str, str]:
        cached = self._labels_cache.get(resource_id)
        if cached is not None:
            return cached
        resource = self.resources[resource_id]
        parent_id = resource["parent_id"]
        merged = {} if parent_id is None else dict(self.effective_labels(parent_id))
        merged.update(resource["labels"])
        self._labels_cache[resource_id] = merged
        return merged

    def in_scope(self, policy_resource_id: str, requested_resource_id: str, include_descendants: bool) -> bool:
        if policy_resource_id == requested_resource_id:
            return True
        if not include_descendants:
            return False
        current = self.resources[requested_resource_id]["parent_id"]
        while current is not None:
            if current == policy_resource_id:
                return True
            current = self.resources[current]["parent_id"]
        return False


class MembershipIndex:
    def __init__(self, memberships: list[dict[str, Any]], groups: dict[str, dict[str, Any]]) -> None:
        self.groups = groups
        self.memberships = sorted(memberships, key=lambda row: row["membership_id"])
        self.principal_edges: dict[str, list[dict[str, Any]]] = defaultdict(list)
        self.group_edges: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for row in self.memberships:
            if row["member_type"] == "PRINCIPAL":
                self.principal_edges[row["member_id"]].append(row)
            else:
                self.group_edges[row["member_id"]].append(row)
        self._validate_acyclic_group_graph()
        self._paths_cache: dict[tuple[str, Any], dict[str, tuple[str, ...]]] = {}

    def _validate_acyclic_group_graph(self) -> None:
        adjacency: dict[str, set[str]] = {group_id: set() for group_id in self.groups}
        indegree = {group_id: 0 for group_id in self.groups}
        for row in self.memberships:
            if row["member_type"] != "GROUP":
                continue
            source = row["member_id"]
            target = row["group_id"]
            if target not in adjacency[source]:
                adjacency[source].add(target)
                indegree[target] += 1

        ready = [group_id for group_id, degree in indegree.items() if degree == 0]
        heapq.heapify(ready)
        visited = 0
        while ready:
            group_id = heapq.heappop(ready)
            visited += 1
            for target in sorted(adjacency[group_id]):
                indegree[target] -= 1
                if indegree[target] == 0:
                    heapq.heappush(ready, target)
        if visited != len(self.groups):
            raise ValueError("current membership graph contains a cycle")

    @staticmethod
    def _is_active(row: dict[str, Any], at_dt) -> bool:
        return row["valid_from_dt"] <= at_dt < row["valid_until_dt"]

    def paths(self, principal_id: str, at_dt) -> dict[str, tuple[str, ...]]:
        cache_key = (principal_id, at_dt)
        cached = self._paths_cache.get(cache_key)
        if cached is not None:
            return cached

        best: dict[str, tuple[int, tuple[str, ...]]] = {}
        heap: list[tuple[int, tuple[str, ...], str]] = []
        for row in self.principal_edges.get(principal_id, []):
            if self._is_active(row, at_dt):
                path = (row["membership_id"],)
                heapq.heappush(heap, (1, path, row["group_id"]))

        while heap:
            length, path, group_id = heapq.heappop(heap)
            if group_id in best:
                continue
            best[group_id] = (length, path)
            for row in self.group_edges.get(group_id, []):
                if self._is_active(row, at_dt):
                    next_path = path + (row["membership_id"],)
                    heapq.heappush(heap, (length + 1, next_path, row["group_id"]))

        result = {group_id: score[1] for group_id, score in best.items()}
        self._paths_cache[cache_key] = result
        return result
