from __future__ import annotations

from collections import defaultdict
from typing import Any


class SessionIndex:
    def __init__(self, events: list[dict[str, Any]], roles: dict[str, dict[str, Any]], memberships) -> None:
        grouped: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for event in events:
            grouped[event["session_id"]].append(event)

        self.roles = roles
        self.memberships = memberships
        self.sessions: dict[str, dict[str, Any]] = {}
        self.by_principal: dict[str, list[str]] = defaultdict(list)
        self._active_cache: dict[tuple[str, Any], bool] = {}

        for session_id in sorted(grouped):
            rows = grouped[session_id]
            requests = [row for row in rows if row["kind"] == "REQUEST"]
            if len(requests) != 1:
                raise ValueError("each current session requires exactly one request")
            approvals = sorted(
                (row for row in rows if row["kind"] == "APPROVE"),
                key=lambda row: (row["effective_at_dt"], row["session_event_id"]),
            )
            revocations = sorted(
                (row for row in rows if row["kind"] == "REVOKE"),
                key=lambda row: (row["effective_at_dt"], row["session_event_id"]),
            )
            session = {
                "session_id": session_id,
                "request": requests[0],
                "approvals": approvals,
                "revocations": revocations,
            }
            self.sessions[session_id] = session
            self.by_principal[requests[0]["principal_id"]].append(session_id)

        for principal_id in self.by_principal:
            self.by_principal[principal_id].sort()

    def get(self, session_id: str) -> dict[str, Any] | None:
        return self.sessions.get(session_id)

    def is_active(self, session_id: str, at_dt) -> bool:
        cache_key = (session_id, at_dt)
        cached = self._active_cache.get(cache_key)
        if cached is not None:
            return cached

        session = self.sessions.get(session_id)
        if session is None:
            self._active_cache[cache_key] = False
            return False

        request = session["request"]
        active = (
            request["effective_at_dt"] <= at_dt
            and request["valid_from_dt"] <= at_dt < request["valid_until_dt"]
        )
        if active:
            for revocation in session["revocations"]:
                if revocation["effective_at_dt"] <= at_dt:
                    active = False
                    break

        if active:
            role = self.roles[request["role_id"]]
            approvers: set[str] = set()
            for approval in session["approvals"]:
                if approval["effective_at_dt"] > at_dt:
                    break
                approver_id = approval["approver_id"]
                if approver_id == request["principal_id"] or approver_id in approvers:
                    continue
                paths = self.memberships.paths(approver_id, approval["effective_at_dt"])
                if role["approver_group_id"] in paths:
                    approvers.add(approver_id)
            active = len(approvers) >= role["approval_threshold"]

        self._active_cache[cache_key] = active
        return active

    def sod_conflicts(self, session_id: str, at_dt) -> list[str]:
        session = self.sessions[session_id]
        request = session["request"]
        incompatible = set(self.roles[request["role_id"]]["incompatible_roles"])
        conflicts: list[str] = []
        for other_id in self.by_principal.get(request["principal_id"], []):
            if other_id == session_id:
                continue
            other = self.sessions[other_id]["request"]
            if other["role_id"] in incompatible and self.is_active(other_id, at_dt):
                conflicts.append(other_id)
        return conflicts
