from __future__ import annotations

from typing import Any


RANK = {"GROUP": 1, "ROLE": 2, "PRINCIPAL": 3}


def evaluate(request: dict[str, Any], model: dict[str, Any], policies: list[dict[str, Any]], memberships, resource_index, active_role_id: str | None):
    at_dt = request["evaluated_at_dt"]
    principal_id = request["principal_id"]
    resource_id = request["resource_id"]
    action = request["action"]
    principal_paths = memberships.paths(principal_id, at_dt)
    resource_labels = resource_index.effective_labels(resource_id)

    applicable: list[tuple[tuple[int, int], dict[str, Any], tuple[str, ...]]] = []
    for policy in policies:
        if not (policy["valid_from_dt"] <= at_dt < policy["valid_until_dt"]):
            continue
        if action not in policy["actions"]:
            continue
        if not resource_index.in_scope(policy["resource_id"], resource_id, policy["include_descendants"]):
            continue
        if any(resource_labels.get(key) != value for key, value in policy["required_labels"].items()):
            continue

        subject_type = policy["subject_type"]
        if subject_type == "PRINCIPAL":
            if policy["subject_id"] != principal_id:
                continue
            subject_path: tuple[str, ...] = ()
        elif subject_type == "GROUP":
            subject_path = principal_paths.get(policy["subject_id"])
            if subject_path is None:
                continue
        else:
            if active_role_id is None or policy["subject_id"] != active_role_id:
                continue
            subject_path = ()

        precedence = (resource_index.depth(policy["resource_id"]), RANK[subject_type])
        applicable.append((precedence, policy, subject_path))

    if not applicable:
        return "DENY", "NO_MATCH", []

    best_precedence = max(item[0] for item in applicable)
    governing = [item for item in applicable if item[0] == best_precedence]
    governing_policies = [
        {
            "policy_id": policy["policy_id"],
            "effect": policy["effect"],
            "subject_path": list(subject_path),
        }
        for _, policy, subject_path in sorted(governing, key=lambda item: item[1]["policy_id"])
    ]
    if any(policy["effect"] == "DENY" for _, policy, _ in governing):
        return "DENY", "POLICY_DENY", governing_policies
    return "ALLOW", "POLICY_ALLOW", governing_policies
