    "op",
    "effect",
    "subject_type",
    "subject_id",
    "resource_id",
    "include_descendants",
    "actions",
    "required_labels",
    "valid_from",
    "valid_until",
}
_SESSION_BASE_UPSERT_KEYS = {
    "session_event_id",
    "revision",
    "published_at",
    "op",
    "session_id",
    "kind",
    "effective_at",
}
_SESSION_REQUEST_KEYS = _SESSION_BASE_UPSERT_KEYS | {
    "principal_id",
    "role_id",
    "valid_from",
    "valid_until",
}
_SESSION_APPROVE_KEYS = _SESSION_BASE_UPSERT_KEYS | {"approver_id"}
_REQUEST_KEYS = {
    "request_id",
    "principal_id",
    "resource_id",
    "action",
    "evaluated_at",
    "session_id",
}
_RETRACT_BASE_KEYS = {
    "revision",
    "published_at",
    "op",
}


def timestamp(value: Any) -> datetime:
    if not isinstance(value, str) or _TS.fullmatch(value) is None:
        raise ValueError("invalid timestamp")
    try:
        parsed = datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
    except ValueError as exc:
        raise ValueError("invalid timestamp") from exc
    if parsed.strftime("%Y-%m-%dT%H:%M:%SZ") != value:
        raise ValueError("non-canonical timestamp")
    return parsed


def exact(value: Any, keys: set[str], label: str) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != keys:
        raise ValueError(f"invalid {label} fields")
    return value


def array(value: Any, label: str) -> list[Any]:
    if not isinstance(value, list):
        raise ValueError(f"{label} must be a list")
    return value


def ident(value: Any, label: str = "identifier") -> str:
    if not isinstance(value, str) or not value:
        raise ValueError(f"invalid {label}")
    return value


def positive_int(value: Any, label: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ValueError(f"invalid {label}")
    return value


def boolean(value: Any, label: str) -> bool:
    if type(value) is not bool:
        raise ValueError(f"invalid {label}")
    return value


def string_list(value: Any, label: str, nonempty: bool = False) -> list[str]:
    result = [ident(item, label) for item in array(value, label)]
    if nonempty and not result:
        raise ValueError(f"empty {label}")
    if len(result) != len(set(result)):
        raise ValueError(f"duplicate {label}")
    return result


def labels(value: Any, label_name: str) -> dict[str, str]:
    if not isinstance(value, dict):
        raise ValueError(f"{label_name} must be an object")
    result: dict[str, str] = {}
    for key, item in value.items():
        result[ident(key, "label key")] = ident(item, "label value")
    return result


def canonical_row(row: dict[str, Any]) -> str:
    return json.dumps(row, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


class ConflictTracker:
    def __init__(self) -> None:
        self._seen: dict[tuple[str, int], str] = {}

    def add(self, logical_id: str, revision: int, row: dict[str, Any], label: str) -> None:
        key = (logical_id, revision)
        encoded = canonical_row(row)
        prior = self._seen.get(key)
        if prior is not None and prior != encoded:
            raise ValueError(f"conflicting {label} revision")
        self._seen[key] = encoded


def _validate_masters(rows: Any, keys: set[str], id_key: str, label: str) -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    for raw in array(rows, label):
        row = exact(raw, keys, label)
        identity = ident(row[id_key], id_key)
        tenant_id = ident(row["tenant_id"], "tenant_id")
        if identity in result:
            raise ValueError(f"duplicate {id_key}")
        result[identity] = {id_key: identity, "tenant_id": tenant_id}
    return result


def _validate_resources(rows: Any) -> dict[str, dict[str, Any]]:
    items = array(rows, "resources")
    if not items:
        raise ValueError("resources must be nonempty")
    resources: dict[str, dict[str, Any]] = {}
    for raw in items:
        row = exact(raw, _RESOURCE_KEYS, "resource")
        resource_id = ident(row["resource_id"], "resource_id")
        tenant_id = ident(row["tenant_id"], "tenant_id")
        parent_id = row["parent_id"]
        if parent_id is not None:
            parent_id = ident(parent_id, "parent_id")
        if resource_id in resources:
            raise ValueError("duplicate resource_id")
        resources[resource_id] = {
            "resource_id": resource_id,
            "tenant_id": tenant_id,
            "parent_id": parent_id,
            "labels": labels(row["labels"], "labels"),
        }

    for resource in resources.values():
        parent_id = resource["parent_id"]
        if parent_id is None:
            continue
        parent = resources.get(parent_id)
        if parent is None:
            raise ValueError("unknown parent resource")
        if parent["tenant_id"] != resource["tenant_id"]:
            raise ValueError("cross-tenant resource parent")

    state: dict[str, int] = {}
    depth_cache: dict[str, int] = {}

    def visit(resource_id: str) -> int:
        marker = state.get(resource_id, 0)
        if marker == 1:
            raise ValueError("resource cycle")
        if marker == 2:
            return depth_cache[resource_id]
        state[resource_id] = 1
        parent_id = resources[resource_id]["parent_id"]
        depth = 0 if parent_id is None else visit(parent_id) + 1
        depth_cache[resource_id] = depth
        state[resource_id] = 2
        return depth

    for resource_id in sorted(resources):
        visit(resource_id)
    return resources


def _validate_roles(rows: Any, groups: dict[str, dict[str, Any]]) -> dict[str, dict[str, Any]]:
    roles: dict[str, dict[str, Any]] = {}
    for raw in array(rows, "roles"):
        row = exact(raw, _ROLE_KEYS, "role")
        role_id = ident(row["role_id"], "role_id")
        tenant_id = ident(row["tenant_id"], "tenant_id")
        approver_group_id = ident(row["approver_group_id"], "approver_group_id")
        approval_threshold = positive_int(row["approval_threshold"], "approval_threshold")
        max_minutes = positive_int(row["max_minutes"], "max_minutes")
        incompatible_roles = string_list(row["incompatible_roles"], "incompatible_roles")
        if role_id in roles:
            raise ValueError("duplicate role_id")
        if role_id in incompatible_roles:
            raise ValueError("self-incompatible role")
        approver_group = groups.get(approver_group_id)
        if approver_group is None or approver_group["tenant_id"] != tenant_id:
            raise ValueError("invalid approver group")
        roles[role_id] = {
            "role_id": role_id,
            "tenant_id": tenant_id,
            "approver_group_id": approver_group_id,
            "approval_threshold": approval_threshold,
            "max_minutes": max_minutes,
            "incompatible_roles": tuple(sorted(incompatible_roles)),
        }

    for role_id, role in roles.items():
        for other_id in role["incompatible_roles"]:
            other = roles.get(other_id)
            if other is None:
                raise ValueError("unknown incompatible role")
            if other["tenant_id"] != role["tenant_id"]:
                raise ValueError("cross-tenant incompatible role")
            if role_id not in other["incompatible_roles"]:
                raise ValueError("asymmetric incompatible roles")
    return roles


def _base_event_fields(raw: dict[str, Any], logical_id_key: str, label: str) -> tuple[str, int, datetime, str]:
    logical_id = ident(raw[logical_id_key], logical_id_key)
    revision = positive_int(raw["revision"], "revision")
    published_at = timestamp(raw["published_at"])
    op = raw["op"]
    if op not in {"UPSERT", "RETRACT"}:
        raise ValueError(f"invalid {label} op")
    return logical_id, revision, published_at, op


def _validate_membership_events(
    rows: Any,
    principals: dict[str, dict[str, Any]],
    groups: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    tracker = ConflictTracker()
    events: list[dict[str, Any]] = []
    for raw in array(rows, "membership_events"):
        if not isinstance(raw, dict):
            raise ValueError("membership_events must contain objects")
        op = raw.get("op")
        if op == "RETRACT":
            keys = {"membership_id"} | _RETRACT_BASE_KEYS
            row = exact(raw, keys, "membership event")
            membership_id, revision, published_at, _ = _base_event_fields(row, "membership_id", "membership")
            tracker.add(membership_id, revision, row, "membership_id")
            events.append(
                {
                    "membership_id": membership_id,
                    "revision": revision,
                    "published_at": row["published_at"],
                    "published_at_dt": published_at,
                    "op": "RETRACT",
                }
            )
            continue

        row = exact(raw, _MEMBERSHIP_UPSERT_KEYS, "membership event")
        membership_id, revision, published_at, op = _base_event_fields(row, "membership_id", "membership")
        member_type = row["member_type"]
        if member_type not in {"PRINCIPAL", "GROUP"}:
            raise ValueError("invalid member_type")
        member_id = ident(row["member_id"], "member_id")
        group_id = ident(row["group_id"], "group_id")
        valid_from = timestamp(row["valid_from"])
        valid_until = timestamp(row["valid_until"])
        if not valid_from < valid_until:
            raise ValueError("invalid membership interval")
        group = groups.get(group_id)
        if group is None:
            raise ValueError("unknown membership group")
        if member_type == "PRINCIPAL":
            member = principals.get(member_id)
            if member is None:
                raise ValueError("unknown membership principal")
        else:
            member = groups.get(member_id)
            if member is None:
                raise ValueError("unknown membership group member")
            if member_id == group_id:
                raise ValueError("group cannot contain itself")
        if member["tenant_id"] != group["tenant_id"]:
            raise ValueError("cross-tenant membership")
        tracker.add(membership_id, revision, row, "membership_id")
        events.append(
            {
                "membership_id": membership_id,
                "revision": revision,
                "published_at": row["published_at"],
                "published_at_dt": published_at,
                "op": op,
                "member_type": member_type,
                "member_id": member_id,
                "group_id": group_id,
                "valid_from": row["valid_from"],
                "valid_from_dt": valid_from,
                "valid_until": row["valid_until"],
                "valid_until_dt": valid_until,
                "tenant_id": group["tenant_id"],
            }
        )
    return events


def _validate_policy_events(
    rows: Any,
    principals: dict[str, dict[str, Any]],
    groups: dict[str, dict[str, Any]],
    roles: dict[str, dict[str, Any]],
    resources: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    tracker = ConflictTracker()
    events: list[dict[str, Any]] = []
    for raw in array(rows, "policy_events"):
        if not isinstance(raw, dict):
            raise ValueError("policy_events must contain objects")
        op = raw.get("op")
        if op == "RETRACT":
            keys = {"policy_id"} | _RETRACT_BASE_KEYS
            row = exact(raw, keys, "policy event")
            policy_id, revision, published_at, _ = _base_event_fields(row, "policy_id", "policy")
            tracker.add(policy_id, revision, row, "policy_id")
            events.append(
                {
                    "policy_id": policy_id,
                    "revision": revision,
                    "published_at": row["published_at"],
                    "published_at_dt": published_at,
                    "op": "RETRACT",
                }
            )
            continue

        row = exact(raw, _POLICY_UPSERT_KEYS, "policy event")
        policy_id, revision, published_at, op = _base_event_fields(row, "policy_id", "policy")
        effect = row["effect"]
        if effect not in {"ALLOW", "DENY"}:
            raise ValueError("invalid effect")
        subject_type = row["subject_type"]
        if subject_type == "PRINCIPAL":
            subject_id = ident(row["subject_id"], "subject_id")
            subject = principals.get(subject_id)
        elif subject_type == "GROUP":
            subject_id = ident(row["subject_id"], "subject_id")
            subject = groups.get(subject_id)
        elif subject_type == "ROLE":
            subject_id = ident(row["subject_id"], "subject_id")
            subject = roles.get(subject_id)
        else:
            raise ValueError("invalid subject_type")
        if subject is None:
            raise ValueError("unknown policy subject")
        resource_id = ident(row["resource_id"], "resource_id")
        resource = resources.get(resource_id)
        if resource is None:
            raise ValueError("unknown policy resource")
        if subject["tenant_id"] != resource["tenant_id"]:
            raise ValueError("cross-tenant policy")
        include_descendants = boolean(row["include_descendants"], "include_descendants")
        actions = tuple(sorted(string_list(row["actions"], "actions", nonempty=True)))
        required_labels = labels(row["required_labels"], "required_labels")
        valid_from = timestamp(row["valid_from"])
        valid_until = timestamp(row["valid_until"])
        if not valid_from < valid_until:
            raise ValueError("invalid policy interval")
        tracker.add(policy_id, revision, row, "policy_id")
        events.append(
            {
                "policy_id": policy_id,
                "revision": revision,
                "published_at": row["published_at"],
                "published_at_dt": published_at,
                "op": op,
                "effect": effect,
                "subject_type": subject_type,
                "subject_id": subject_id,
                "resource_id": resource_id,
                "include_descendants": include_descendants,
                "actions": actions,
                "required_labels": required_labels,
                "valid_from": row["valid_from"],
                "valid_from_dt": valid_from,
                "valid_until": row["valid_until"],
                "valid_until_dt": valid_until,
                "tenant_id": resource["tenant_id"],
            }
        )
    return events


def _validate_session_events(
    rows: Any,
    principals: dict[str, dict[str, Any]],
    roles: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    tracker = ConflictTracker()
    events: list[dict[str, Any]] = []
    for raw in array(rows, "session_events"):
        if not isinstance(raw, dict):
            raise ValueError("session_events must contain objects")
        op = raw.get("op")
        if op == "RETRACT":
            keys = {"session_event_id"} | _RETRACT_BASE_KEYS
            row = exact(raw, keys, "session event")
            session_event_id, revision, published_at, _ = _base_event_fields(row, "session_event_id", "session event")
            tracker.add(session_event_id, revision, row, "session_event_id")
            events.append(
                {
                    "session_event_id": session_event_id,
                    "revision": revision,
                    "published_at": row["published_at"],
                    "published_at_dt": published_at,
                    "op": "RETRACT",
                }
            )
            continue

        if not isinstance(raw, dict):
            raise ValueError("session event must be an object")
        kind = raw.get("kind")
        if kind == "REQUEST":
            row = exact(raw, _SESSION_REQUEST_KEYS, "session event")
        elif kind == "APPROVE":
            row = exact(raw, _SESSION_APPROVE_KEYS, "session event")
        elif kind == "REVOKE":
            row = exact(raw, _SESSION_BASE_UPSERT_KEYS, "session event")
        else:
            raise ValueError("invalid session kind")

        session_event_id, revision, published_at, event_op = _base_event_fields(row, "session_event_id", "session event")
        session_id = ident(row["session_id"], "session_id")
        effective_at = timestamp(row["effective_at"])
        if published_at < effective_at:
            raise ValueError("session event published before effective time")

        normalized: dict[str, Any] = {
            "session_event_id": session_event_id,
            "revision": revision,
            "published_at": row["published_at"],
            "published_at_dt": published_at,
            "op": event_op,
            "session_id": session_id,
            "kind": kind,
            "effective_at": row["effective_at"],
            "effective_at_dt": effective_at,
        }

        if kind == "REQUEST":
            principal_id = ident(row["principal_id"], "principal_id")
            role_id = ident(row["role_id"], "role_id")
            principal = principals.get(principal_id)
            role = roles.get(role_id)
            if principal is None:
                raise ValueError("unknown session principal")
            if role is None:
                raise ValueError("unknown session role")
            if principal["tenant_id"] != role["tenant_id"]:
                raise ValueError("cross-tenant session request")
            valid_from = timestamp(row["valid_from"])
            valid_until = timestamp(row["valid_until"])
            if not (effective_at <= valid_from < valid_until):
                raise ValueError("invalid session request interval")
            if (valid_until - valid_from).total_seconds() > role["max_minutes"] * 60:
                raise ValueError("session exceeds role max_minutes")
            normalized.update(
                {
                    "principal_id": principal_id,
                    "role_id": role_id,
                    "valid_from": row["valid_from"],
                    "valid_from_dt": valid_from,
                    "valid_until": row["valid_until"],
                    "valid_until_dt": valid_until,
                    "tenant_id": principal["tenant_id"],
                }
            )
        elif kind == "APPROVE":
            approver_id = ident(row["approver_id"], "approver_id")
            if approver_id not in principals:
                raise ValueError("unknown session approver")
            normalized["approver_id"] = approver_id
        tracker.add(session_event_id, revision, row, "session_event_id")
        events.append(normalized)
    return events


def _validate_requests(
    rows: Any,
    as_of_dt: datetime,
    principals: dict[str, dict[str, Any]],
    resources: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    seen: set[str] = set()
    requests: list[dict[str, Any]] = []
    for raw in array(rows, "requests"):
        row = exact(raw, _REQUEST_KEYS, "request")
        request_id = ident(row["request_id"], "request_id")
        if request_id in seen:
            raise ValueError("duplicate request_id")
        principal_id = ident(row["principal_id"], "principal_id")
        resource_id = ident(row["resource_id"], "resource_id")
        action = ident(row["action"], "action")
        evaluated_at = timestamp(row["evaluated_at"])
        session_id = row["session_id"]
        if session_id is not None:
            session_id = ident(session_id, "session_id")
        principal = principals.get(principal_id)
        if principal is None:
            raise ValueError("unknown request principal")
        resource = resources.get(resource_id)
        if resource is None:
            raise ValueError("unknown request resource")
        if principal["tenant_id"] != resource["tenant_id"]:
            raise ValueError("cross-tenant request")
        if evaluated_at > as_of_dt:
            raise ValueError("request after as_of")
        seen.add(request_id)
        requests.append(
            {
                "request_id": request_id,
                "principal_id": principal_id,
                "resource_id": resource_id,
                "action": action,
                "evaluated_at": row["evaluated_at"],
                "evaluated_at_dt": evaluated_at,
                "session_id": session_id,
                "tenant_id": principal["tenant_id"],
            }
        )
    return requests


def validate_payload(payload: Any) -> dict[str, Any]:
    data = exact(payload, _PAYLOAD_KEYS, "payload")
    as_of = ident(data["as_of"], "as_of")
    knowledge_cutoff = ident(data["knowledge_cutoff"], "knowledge_cutoff")
    as_of_dt = timestamp(as_of)
    cutoff_dt = timestamp(knowledge_cutoff)

    principals = _validate_masters(data["principals"], {"principal_id", "tenant_id"}, "principal_id", "principal")
    groups = _validate_masters(data["groups"], {"group_id", "tenant_id"}, "group_id", "group")
    roles = _validate_roles(data["roles"], groups)
    resources = _validate_resources(data["resources"])
    membership_events = _validate_membership_events(data["membership_events"], principals, groups)
    policy_events = _validate_policy_events(data["policy_events"], principals, groups, roles, resources)
    session_events = _validate_session_events(data["session_events"], principals, roles)
    requests = _validate_requests(data["requests"], as_of_dt, principals, resources)

    return {
        "as_of": as_of,
        "as_of_dt": as_of_dt,
        "knowledge_cutoff": knowledge_cutoff,
        "cutoff_dt": cutoff_dt,
        "principals": principals,
        "groups": groups,
        "roles": roles,
        "resources": resources,
        "membership_events": membership_events,
        "policy_events": policy_events,
        "session_events": session_events,
        "requests": requests,
    }
