def resolve(rows: list[dict[str, Any]], id_key: str, cutoff) -> list[dict[str, Any]]:
    grouped: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in rows:
        if row["published_at_dt"] <= cutoff:
            grouped[row[id_key]].append(row)

    resolved: list[dict[str, Any]] = []
