from __future__ import annotations

import hashlib
import json
from typing import Any

from .common import validate_payload
from .graph import MembershipIndex, ResourceIndex
from .policy import evaluate
from .sessions import SessionIndex
from .visibility import resolve


def _terminal_decision(request: dict[str, Any], reason: str, conflicts: list[str]) -> dict[str, Any]:
    return {
        "request_id": request["request_id"],
        "principal_id": request["principal_id"],
        "resource_id": request["resource_id"],
        "action": request["action"],
        "evaluated_at": request["evaluated_at"],
        "decision": "DENY",
        "reason": reason,
        "governing_policies": [],
        "conflicting_sessions": conflicts,
    }


def evaluate_batch(payload: Any) -> dict[str, Any]:
    model = validate_payload(payload)
    memberships = resolve(model["membership_events"], "membership_id", model["cutoff_dt"])
    policies = resolve(model["policy_events"], "policy_id", model["cutoff_dt"])
    session_events = resolve(model["session_events"], "session_event_id", model["cutoff_dt"])

    resource_index = ResourceIndex(model["resources"])
    membership_index = MembershipIndex(memberships, model["groups"])
    session_index = SessionIndex(session_events, model["roles"], membership_index)

    decisions: list[dict[str, Any]] = []
    for request in sorted(model["requests"], key=lambda row: row["request_id"]):
        active_role_id: str | None = None
        session_id = request["session_id"]
        if session_id is not None:
            session = session_index.get(session_id)
            if session is None or session["request"]["principal_id"] != request["principal_id"]:
                decisions.append(_terminal_decision(request, "SESSION_INVALID", []))
                continue
            if not session_index.is_active(session_id, request["evaluated_at_dt"]):
                decisions.append(_terminal_decision(request, "SESSION_INVALID", []))
                continue
            conflicts = session_index.sod_conflicts(session_id, request["evaluated_at_dt"])
            if conflicts:
                decisions.append(_terminal_decision(request, "SOD_CONFLICT", conflicts))
                continue
            active_role_id = session["request"]["role_id"]

        decision, reason, governing_policies = evaluate(
            request,
            model,
            policies,
            membership_index,
            resource_index,
            active_role_id,
        )
        decisions.append(
            {
                "request_id": request["request_id"],
                "principal_id": request["principal_id"],
                "resource_id": request["resource_id"],
                "action": request["action"],
                "evaluated_at": request["evaluated_at"],
                "decision": decision,
                "reason": reason,
                "governing_policies": governing_policies,
                "conflicting_sessions": [],
            }
        )

    tenant_ids = sorted({principal["tenant_id"] for principal in model["principals"].values()})
    tenant_totals = {
        tenant_id: {
            "tenant_id": tenant_id,
            "requests": 0,
            "allowed": 0,
            "denied": 0,
            "policy_denied": 0,
            "session_denied": 0,
            "sod_denied": 0,
            "no_match": 0,
        }
        for tenant_id in tenant_ids
    }
    reason_counter = {
        "POLICY_DENY": "policy_denied",
        "SESSION_INVALID": "session_denied",
        "SOD_CONFLICT": "sod_denied",
        "NO_MATCH": "no_match",
    }
    for decision in decisions:
        tenant_total = tenant_totals[model["principals"][decision["principal_id"]]["tenant_id"]]
        tenant_total["requests"] += 1
        if decision["decision"] == "ALLOW":
            tenant_total["allowed"] += 1
        else:
            tenant_total["denied"] += 1
            tenant_total[reason_counter[decision["reason"]]] += 1

    ordered_totals = [tenant_totals[tenant_id] for tenant_id in tenant_ids]
    digest_payload = {"decisions": decisions, "tenant_totals": ordered_totals}
    digest = hashlib.sha256(
        json.dumps(digest_payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    ).hexdigest()
    return {
        "as_of": model["as_of"],
        "knowledge_cutoff": model["knowledge_cutoff"],
        "decisions": decisions,
        "tenant_totals": ordered_totals,
        "snapshot_digest": digest,
    }
